create or replace function public.crm2_record_inventory_movement(p_sku text,p_warehouse_id uuid,p_movement_type text,p_quantity integer,p_reason text default null,p_reference_type text default null,p_reference_id uuid default null) returns jsonb language plpgsql security invoker set search_path=public as $$ declare v_user uuid:=auth.uid(); v_on_hand integer; v_reserved integer; v_damaged integer; begin if v_user is null then raise exception 'Authentication required'; end if; if p_quantity is null or p_quantity<=0 then raise exception 'Quantity must be greater than zero'; end if; if p_movement_type not in ('inward','outward','reserve','release','damage','return','adjustment') then raise exception 'Unsupported movement type'; end if; select on_hand,reserved,damaged into v_on_hand,v_reserved,v_damaged from inventory where sku=p_sku and warehouse_id=p_warehouse_id for update; if not found then insert into inventory(sku,warehouse_id,on_hand,reserved,damaged) values(p_sku,p_warehouse_id,0,0,0) returning on_hand,reserved,damaged into v_on_hand,v_reserved,v_damaged; end if; if p_movement_type in ('inward','return') then v_on_hand:=v_on_hand+p_quantity; elsif p_movement_type='outward' then if v_on_hand-v_reserved<p_quantity then raise exception 'Insufficient available stock'; end if; v_on_hand:=v_on_hand-p_quantity; elsif p_movement_type='reserve' then if v_on_hand-v_reserved<p_quantity then raise exception 'Insufficient available stock'; end if; v_reserved:=v_reserved+p_quantity; elsif p_movement_type='release' then if v_reserved<p_quantity then raise exception 'Reserved stock cannot go below zero'; end if; v_reserved:=v_reserved-p_quantity; elsif p_movement_type='damage' then if v_on_hand-v_reserved-v_damaged<p_quantity then raise exception 'Insufficient free stock for damage adjustment'; end if; v_damaged:=v_damaged+p_quantity; v_on_hand:=v_on_hand-p_quantity; else v_on_hand:=v_on_hand+p_quantity; end if; update inventory set on_hand=v_on_hand,reserved=v_reserved,damaged=v_damaged,updated_at=now() where sku=p_sku and warehouse_id=p_warehouse_id; insert into inventory_movements(sku,warehouse_id,movement_type,quantity,reference_type,reference_id,reason,created_by) values(p_sku,p_warehouse_id,p_movement_type,p_quantity,p_reference_type,p_reference_id,p_reason,v_user); insert into audit_logs(actor_id,action,entity_type,metadata) values(v_user,'inventory_movement','inventory',jsonb_build_object('sku',p_sku,'warehouse_id',p_warehouse_id,'movement_type',p_movement_type,'quantity',p_quantity,'reason',p_reason)); return jsonb_build_object('sku',p_sku,'warehouse_id',p_warehouse_id,'on_hand',v_on_hand,'reserved',v_reserved,'damaged',v_damaged); end; $$;
revoke all on function public.crm2_record_inventory_movement(text,uuid,text,integer,text,text,uuid) from public; grant execute on function public.crm2_record_inventory_movement(text,uuid,text,integer,text,text,uuid) to authenticated;
create or replace function public.crm2_record_cod_remittance(p_shipment_id uuid,p_amount numeric,p_courier text,p_reference text default null,p_status text default 'remitted') returns uuid language plpgsql security invoker set search_path=public as $$ declare v_id uuid; v_user uuid:=auth.uid(); begin if v_user is null then raise exception 'Authentication required'; end if; if p_amount is null or p_amount<0 then raise exception 'Invalid amount'; end if; insert into cod_remittances(shipment_id,amount,courier,status,remitted_at,reference) values(p_shipment_id,p_amount,p_courier,p_status,case when p_status='remitted' then now() else null end,p_reference) returning id into v_id; insert into audit_logs(actor_id,action,entity_type,entity_id,metadata) values(v_user,'cod_remittance','cod_remittance',v_id,jsonb_build_object('shipment_id',p_shipment_id,'amount',p_amount,'status',p_status)); return v_id; end; $$;
revoke all on function public.crm2_record_cod_remittance(uuid,numeric,text,text,text) from public; grant execute on function public.crm2_record_cod_remittance(uuid,numeric,text,text,text) to authenticated;
create or replace function public.crm2_record_settlement(p_party_type text,p_party_id uuid,p_amount numeric,p_reference text default null,p_status text default 'pending') returns uuid language plpgsql security invoker set search_path=public as $$ declare v_id uuid; v_user uuid:=auth.uid(); begin if v_user is null then raise exception 'Authentication required'; end if; if p_amount is null or p_amount<0 then raise exception 'Invalid amount'; end if; if p_party_type not in ('dealer','distributor','courier','other') then raise exception 'Unsupported party type'; end if; insert into settlements(party_type,party_id,amount,status,reference) values(p_party_type,p_party_id,p_amount,p_status,p_reference) returning id into v_id; insert into audit_logs(actor_id,action,entity_type,entity_id,metadata) values(v_user,'settlement_created','settlement',v_id,jsonb_build_object('party_type',p_party_type,'party_id',p_party_id,'amount',p_amount,'status',p_status)); return v_id; end; $$;
revoke all on function public.crm2_record_settlement(text,uuid,numeric,text,text) from public; grant execute on function public.crm2_record_settlement(text,uuid,numeric,text,text) to authenticated;
create or replace function public.crm2_record_refund(p_order_id uuid,p_amount numeric,p_reference text default null,p_status text default 'requested') returns uuid language plpgsql security invoker set search_path=public as $$ declare v_id uuid; v_user uuid:=auth.uid(); begin if v_user is null then raise exception 'Authentication required'; end if; if p_amount is null or p_amount<0 then raise exception 'Invalid amount'; end if; insert into refunds(order_id,amount,status,reference) values(p_order_id,p_amount,p_status,p_reference) returning id into v_id; insert into audit_logs(actor_id,action,entity_type,entity_id,metadata) values(v_user,'refund_created','refund',v_id,jsonb_build_object('order_id',p_order_id,'amount',p_amount,'status',p_status)); return v_id; end; $$;
revoke all on function public.crm2_record_refund(uuid,numeric,text,text) from public; grant execute on function public.crm2_record_refund(uuid,numeric,text,text) to authenticated;
